#!/usr/bin/env bash
set -Eeuo pipefail; STAGE=tools; printf 'STAGE=%s\n' "$STAGE"; command -v umbreld >/dev/null || { printf 'UNVERIFIED umbreld_missing\n'; exit 20; }; printf 'umbreld=%s\n' "$(command -v umbreld)"; STAGE=umbrel_root; printf 'STAGE=%s\n' "$STAGE"; ROOT=/home/umbrel/umbrel; test -d "$ROOT"; printf 'root=%s\n' "$ROOT"; STAGE=app_store_candidates; printf 'STAGE=%s\n' "$STAGE"; p="$ROOT/app-store"; if test -d "$p"; then stat --printf='dir=%n owner=%U:%G mode=%a\n' -- "$p"; fi; p="$ROOT/apps"; if test -d "$p"; then stat --printf='dir=%n owner=%U:%G mode=%a\n' -- "$p"; fi; p="$ROOT/umbrel-apps"; if test -d "$p"; then stat --printf='dir=%n owner=%U:%G mode=%a\n' -- "$p"; fi; p="$ROOT/app-data"; if test -d "$p"; then stat --printf='dir=%n owner=%U:%G mode=%a\n' -- "$p"; fi; STAGE=runner_paths; printf 'STAGE=%s\n' "$STAGE"; p=/run/zeus-host-runner.sock; if test -e "$p"; then stat --printf='existing=%n type=%F owner=%U:%G mode=%a\n' -- "$p"; fi; p=/run/zeus-host-runner; if test -e "$p"; then stat --printf='existing=%n type=%F owner=%U:%G mode=%a\n' -- "$p"; fi; p=/var/lib/zeus-host-runner; if test -e "$p"; then stat --printf='existing=%n type=%F owner=%U:%G mode=%a\n' -- "$p"; fi; p=/etc/zeus-host-runner; if test -e "$p"; then stat --printf='existing=%n type=%F owner=%U:%G mode=%a\n' -- "$p"; fi; STAGE=docker_metadata; printf 'STAGE=%s\n' "$STAGE"; if test -S /var/run/docker.sock; then stat --printf='docker_socket=%n owner=%U:%G mode=%a\n' /var/run/docker.sock; else printf 'docker_socket=absent\n'; fi; printf 'NO_MUTATION=TRUE\nNO_SECRET_READ=TRUE\nNO_DOCKER_OPERATION=TRUE\n'
